    public function run(): void
    {
        /*
         * Large JSON columns are written in separate compact updates.
         * This follows the reference V2/V3 format and lowers the risk of
         * "MySQL server has gone away" errors on local XAMPP installations.
         */
        $now = now();

        DB::table('module_library_items')->updateOrInsert(
            ['module_code' => 'MATH-ANALYSIS-I-BASIC-V1'],
            [
                'module_no' => 4,
                'title' => 'Mathematical Analysis I',
                'year_level' => 'Year 1',
                'version_no' => 1,
                'version_name' => 'Mathematical Analysis I Fundamentals',
                'version_code' => 'V1',
                'description' => 'Limits, continuity, differentiation, and integration. The mathematical foundation for machine learning and modeling. This version emphasizes concept foundations, guided examples, careful interpretation, and beginner assessment readiness.',
                'estimated_minutes' => 500,
                'sort_order' => 10,
                'is_active' => true,
                'created_at' => $now,
                'updated_at' => $now,
            ]
        );

        DB::table('module_library_items')
            ->where('module_code', 'MATH-ANALYSIS-I-BASIC-V1')
            ->update([
                'content_sections' => json_encode($this->contentSections(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);

        DB::table('module_library_items')
            ->where('module_code', 'MATH-ANALYSIS-I-BASIC-V1')
            ->update([
                'mcq_questions' => json_encode($this->mcqQuestions(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);
    }

